function copyText_uni() {

    var x = document.getElementById("myText").select();

    document.execCommand('Copy');
    // alert("Text Copied to Clipboard succesfully!");
    swal("Done", "Text Copied to Clipboard succesfully!", "success");

}

function cutText_uni() {

    var x = document.getElementById("myText").select();

    document.execCommand('Cut');
    // alert("Text Cut to Clipboard succesfully!");
    swal("Done", "Text Cut to Clipboard succesfully!", "success");

}